"""Exercise the final route checker with synthetic, non-observational records; launch no Java."""
import argparse
from copy import deepcopy
import hashlib
import json
from pathlib import Path
import subprocess
import sys

BENCH = Path(__file__).resolve().parents[1]
CHECKER = BENCH / 'check_route_profile.py'
FIXTURE = 'synthetic-late-cold-hot'
RAW_FILES = ('launch.json', 'process.json', 'inputs-before.json', 'inputs-after.json',
             'console.log', 'samples.jsonl', 'gc.log', 'validation.json')
ROUTE_COUNTERS = ('irPlanned', 'irOpened', 'irRows', 'semanticNativeCompiles', 'compiledBinds',
                  'interpretedBinds', 'aggregateCompiledBinds', 'aggregateInterpretedBinds',
                  'hostedGeneric', 'unhostedHardDeclines', 'chunkEngaged',
                  'leftJoinReplayMaterializations', 'factorizedEngagement')


def need(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def object_sha(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, allow_nan=False).encode()).hexdigest()


def write(path, value):
    with path.open('x') as output:
        json.dump(value, output, indent=2, sort_keys=True, allow_nan=False)
        output.write('\n')


def synthetic_route(index):
    counters = dict.fromkeys(ROUTE_COUNTERS, 0)
    counters.update(semanticNativeCompiles=1, chunkEngaged=1, factorizedEngagement=1)
    return {'selections': [{'point': 'ORDER', 'label': 'synthetic validator fixture',
                            'strategy': 'orderedFactorizedSort', 'mode': 'normal', 'count': 1}],
            'counters': counters, 'nativeProjectedRows': 32768,
            'adjacency': {'lookupHits': 98309 if index < 8 else 98308, 'syntheticOnly': True}}


def make_case(root, corrupt):
    root.mkdir()
    (root / 'claims').mkdir()
    folder = root / 'round-synthetic-only'
    folder.mkdir()
    profiles = {FIXTURE: [synthetic_route(index) for index in range(13)]}
    qualification_file = root / 'synthetic-qualification.json'
    qualification = {'syntheticOnly': True, 'observational': False,
        'purpose': 'Narrow validator test data; not a qualified runtime or runnable benchmark protocol',
        'format': 'growth-final-runtime-qualification-v1', 'qualifiedForTiming': True,
        'exactOracleQualified': True, 'fixtureDefinitionsSha256': object_sha('synthetic definitions'),
        'runtimeInputsSha256': object_sha('synthetic runtime; Java is never launched'),
        'qualifiedRouteProfiles': profiles, 'qualifiedRouteProfilesSha256': object_sha(profiles)}
    write(qualification_file, qualification)
    protocol_file = root / 'protocol.json'
    protocol = {'syntheticOnly': True, 'observational': False, 'runnable': False,
        'format': 'rdf4j-phase-growth-comparison-v1', 'cohort': str(root), 'warmups': 8, 'measurements': 5,
        'qualificationFile': str(qualification_file),
        'fixtureDefinitionsSha256': qualification['fixtureDefinitionsSha256'],
        'runtimeInputsSha256': qualification['runtimeInputsSha256'], 'fixtures': {FIXTURE: {'syntheticOnly': True}},
        'inputs': [{'path': str(path), 'kind': 'file', 'bytes': path.stat().st_size, 'sha256': sha(path)}
                   for path in (qualification_file, CHECKER)],
        'schedule': [{'ordinal': 0, 'fixture': FIXTURE, 'arm': 'fixed', 'directory': str(folder)}]}
    write(protocol_file, protocol)
    with (root / 'protocol.sha256').open('x') as output:
        output.write(sha(protocol_file) + '\n')
    claim_file = root / 'claims/0000.json'
    write(claim_file, {'syntheticOnly': True, 'ordinal': 0, 'protocolSha256': sha(protocol_file), 'javaLaunched': False})
    records = [{'type': 'metadata', 'syntheticOnly': True, 'observational': False, 'javaLaunched': False}]
    for index in range(13):
        route = deepcopy(profiles[FIXTURE][index])
        record = {'type': 'sample', 'syntheticOnly': True, 'observational': False, 'arm': 'fixed',
                  'iteration': index - 8, 'stage': 'warmup' if index < 8 else 'measurement',
                  'successfulSelections': route['selections'], 'counters': route['counters'],
                  'nativeProjectedRows': route['nativeProjectedRows'], 'adjacency': route['adjacency']}
        if corrupt and index == 8:
            record['adjacency']['lookupHits'] += 1
        records.append(record)
    records.append({'type': 'completion', 'syntheticOnly': True, 'observational': False, 'harnessReturned': False})
    with (folder / 'samples.jsonl').open('x') as output:
        for record in records:
            output.write(json.dumps(record, sort_keys=True) + '\n')
    for name in RAW_FILES:
        if name == 'samples.jsonl':
            continue
        if name.endswith('.log'):
            with (folder / name).open('x') as output:
                output.write('SYNTHETIC VALIDATOR TEST ONLY. No JVM, query or measurement occurred.\n')
        else:
            record = {'syntheticOnly': True, 'observational': False, 'javaLaunched': False}
            if name == 'process.json':
                record.update(exitCode=0, failure=None)
            write(folder / name, record)
    # Seal after introducing the negative-control change. Rejection must therefore be semantic,
    # not merely a stale raw checksum. Neither case is a valid full runner protocol.
    completion = {'syntheticOnly': True, 'ordinal': 0, 'protocolSha256': sha(protocol_file),
                  'claimSha256': sha(claim_file), 'rawHashes': {name: sha(folder / name) for name in RAW_FILES}}
    write(folder / 'completion.json', completion)
    need(all(sha(folder / name) == digest for name, digest in completion['rawHashes'].items()),
         'Synthetic raw seal failed before invoking checker')
    return {'rawSealsRecomputedAndVerified': True, 'profileSha256': object_sha(profiles),
            'sampleSha256': sha(folder / 'samples.jsonl'), 'completionSha256': sha(folder / 'completion.json')}


def run_checker(root):
    output = root / 'checker-result.json'
    command = [sys.executable, '-B', str(CHECKER), '--cohort', str(root), '--output', str(output)]
    process = subprocess.run(command, capture_output=True, text=True, check=False)
    with (root / 'checker-console.txt').open('x') as console:
        console.write(process.stdout)
        console.write(process.stderr)
    return process.returncode, json.loads(output.read_text())


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', required=True, type=Path)
    args = parser.parse_args()
    root = args.output.resolve()
    root.mkdir(parents=True, exist_ok=False)
    checker_before = sha(CHECKER)
    positive = make_case(root / 'positive-synthetic', False)
    positive_code, positive_result = run_checker(root / 'positive-synthetic')
    need(positive_code == 0 and positive_result['passed'] is True
         and positive_result['queriesChecked'] == 13
         and positive_result['timingOrAllocationAnalysisPerformed'] is False, 'Valid synthetic profile was rejected')
    negative = make_case(root / 'resealed-corruption-synthetic', True)
    negative_code, negative_result = run_checker(root / 'resealed-corruption-synthetic')
    expected_failure = 'Qualified route differs: JVM 0, query 8, fixture ' + FIXTURE
    need(negative_code == 1 and negative_result['passed'] is False
         and negative_result['failure'] == expected_failure
         and negative_result['timingOrAllocationAnalysisPerformed'] is False,
         'Resealed corruption was not rejected at the intended query-ordinal profile comparison')
    need(positive['profileSha256'] == negative['profileSha256'] and checker_before == sha(CHECKER),
         'Expected profile or checker changed between controls')
    result = {'passed': True, 'syntheticOnly': True, 'observational': False, 'javaLaunches': 0,
        'pilotFilesRead': 0, 'latencyOrAllocationFieldsCreatedOrRead': 0,
        'checkerSha256': checker_before, 'testSourceSha256': sha(Path(__file__).resolve()),
        'positive': {'exitCode': positive_code, 'queriesChecked': 13, **positive},
        'negative': {'exitCode': negative_code, 'rejectedAtZeroBasedQuery': 8, 'changedField': 'adjacency.lookupHits',
                     'expected': 98308, 'corrupted': 98309, 'failure': negative_result['failure'], **negative},
        'scope': 'Synthetic route-checker control only. No runtime qualification, query observation or timing sample.'}
    write(root / 'RESULT.json', result)
    print(json.dumps(result, sort_keys=True))


if __name__ == '__main__':
    main()
